[strategy/guidance/application/implementation/GUID-APP-IMPL-002-extension-pattern-cookbook.md#integration-points]

#### Integration Points

**Rule Engine Registration:**

```csharp
// Extensions/Rules/ClaimsValidationRuleEngine.cs
public class ClaimsValidationRuleEngine : IRuleEngine
{
    private readonly IServiceProvider _serviceProvider;
    private readonly IRuleRepository _ruleRepository;

    public ClaimsValidationRuleEngine(
        IServiceProvider serviceProvider,
        IRuleRepository ruleRepository)
    {
        _serviceProvider = serviceProvider;
        _ruleRepository = ruleRepository;
    }

    public async Task<ValidationResult> ExecuteRulesAsync(Claim claim, CancellationToken ct)
    {
        var rules = await _ruleRepository.GetRulesAsync(claim.StateCode, ct);
        var context = new RuleContext(claim, _serviceProvider);

        var results = new List<RuleResult>();
        foreach (var rule in rules)
        {
            var result = await ExecuteRuleAsync(rule, context, ct);
            results.Add(result);

            if (result.StopProcessing) break;
        }

        return AggregateResults(results);
    }
}

// Startup.cs - Register with product
services.AddExtension<ClaimsValidationRuleEngine>(config => {
    config.HookPoint = "Claims.Validation";
    config.Priority = 100;
});
```

**Custom Rule Provider Plugin:**

```csharp
// Extensions/Rules/Providers/ProviderCredentialPlugin.cs
[Plugin("ProviderCredential")]
public class ProviderCredentialPlugin : IRuleProvider
{
    private readonly IProviderRegistryClient _registryClient;

    public ProviderCredentialPlugin(IProviderRegistryClient registryClient)
    {
        _registryClient = registryClient;
    }

    public async Task<object> EvaluateAsync(RuleContext context, Dictionary<string, object> args)
    {
        var providerId = context.GetValue<string>("ProviderId");
        var credentialType = args["CredentialType"].ToString();

        var credentials = await _registryClient.GetCredentialsAsync(providerId);
        return credentials.Any(c => c.Type == credentialType && c.IsActive);
    }
}

// Register plugin
services.AddPlugin<ProviderCredentialPlugin>();
```

**Rule DSL Example:**

```json
{
  "ruleId": "TX_PROVIDER_CREDENTIAL_CHECK",
  "name": "Texas Provider Credential Validation",
  "condition": {
    "all": [
      { "fact": "claim.serviceType", "operator": "equal", "value": "Surgery" },
      { "fact": "claim.amount", "operator": "greaterThan", "value": 5000 }
    ]
  },
  "actions": [
    {
      "type": "validateProvider",
      "provider": "ProviderCredential",
      "args": {
        "CredentialType": "Surgery",
        "RequireActive": true
      },
      "onFailure": {
        "severity": "Error",
        "message": "Provider lacks active surgery credentials"
      }
    }
  ]
}
```

> **Rule DSL Injection Security Requirement:** Rule DSL JSON supplied by or on behalf of a tenant is tenant-controlled input and must be treated as untrusted. Before deserialisation and registration:
>
> 1. **Schema validation**: Validate the rule document against a strict JSON Schema to reject unexpected properties, unknown operators, and unbounded nesting depth.
> 2. **Provider allowlist**: The `provider` field must be validated against a per-tenant allowlist of registered providers — a tenant must not be able to reference providers outside their authorised scope.
> 3. **Depth and complexity limits**: Enforce maximum nesting depth on `condition` trees and a maximum rule count per tenant to prevent rule engine resource exhaustion.
>
> Refer to [STD-SEC-APP-001 §3.3 Input Validation](../../../../standards/security/application/STD-SEC-APP-001-application-security.md) and [§3.4 API Security](../../../../standards/security/application/STD-SEC-APP-001-application-security.md) for the validation and injection prevention requirements applicable to all tenant-supplied configuration.

