```typescript
// Extensions/Theming/TenantThemeProvider.tsx
import { ThemeProvider } from '@emotion/react';
import { useTenantContext } from '@product/tenant-context';
import { useThemeConfiguration } from './hooks/useThemeConfiguration';

export const TenantThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { tenantId } = useTenantContext();
  const { theme, loading } = useThemeConfiguration(tenantId);

  if (loading) {
    return <ThemeLoadingSkeleton />;
  }

  return (
    <ThemeProvider theme={theme}>
      {children}
    </ThemeProvider>
  );
};

// Hook for loading theme configuration
const useThemeConfiguration = (tenantId: string) => {
  return useQuery(['tenant-theme', tenantId], async () => {
    const config = await themingApi.getTenantTheme(tenantId);
    return buildThemeFromConfig(config);
  }, {
    staleTime: 1000 * 60 * 60, // Cache 1 hour
    cacheTime: 1000 * 60 * 60 * 24, // Keep in cache 24 hours
  });
};
```

