#### Integration Points

**Module Federation Configuration:**

```javascript
// webpack.config.js - MFE Remote
const ModuleFederationPlugin = require('webpack/lib/container/ModuleFederationPlugin');

module.exports = {
  plugins: [
    new ModuleFederationPlugin({
      name: 'providerSearchMFE',
      filename: 'remoteEntry.js',
      exposes: {
        './ProviderSearch': './src/ProviderSearch',
        './ProviderSearchRoutes': './src/routes'
      },
      shared: {
        react: { singleton: true, requiredVersion: '^18.0.0' },
        'react-dom': { singleton: true, requiredVersion: '^18.0.0' },
        '@product/design-system': { singleton: true },
        '@product/state-management': { singleton: true }
      }
    })
  ]
};

// webpack.config.js - Product Host
new ModuleFederationPlugin({
  name: 'productHost',
  remotes: {
    providerSearchMFE: `providerSearchMFE@${process.env.MFE_PROVIDER_SEARCH_URL}/remoteEntry.js`
  },
  shared: { /* same shared deps */ }
});
```

**MFE Remote Entry:**

```typescript
// src/ProviderSearch.tsx - MFE exposed component
