**Host Loading MFE (PTN-APP-MTN-012):**

```typescript
// Product Host - Lazy load MFE
import React, { lazy, Suspense } from 'react';

const ProviderSearchMFE = lazy(() => {
  // Check if tenant has MFE enabled (PTN-APP-MTN-012)
  const tenantConfig = getTenantConfiguration(tenantId);
  if (tenantConfig.features.providerSearchMFE?.enabled) {
    return import('providerSearchMFE/ProviderSearch');
  } else {
    // Fallback to default product provider search
    return import('./DefaultProviderSearch');
  }
});

export const ProviderSearchPage: React.FC = () => {
  const { tenantId, userId } = useUserContext();

  return (
    <Suspense fallback={<ProviderSearchSkeleton />}>
      <ProviderSearchMFE stateCode={tenantId} userId={userId} />
    </Suspense>
  );
};
```

**State Integration (PTN-APP-EXT-018):**

```typescript
// MFE accessing host state
import { useProductState } from '@product/state-management';

const SearchFilters: React.FC = () => {
  // Access shared host state (PTN-APP-EXT-018)
  const { userContext, authToken } = useProductState(state => ({
    userContext: state.auth.user,
    authToken: state.auth.token
  }));

  // MFE local state
  const [filters, setFilters] = useState<SearchFilters>({
    specialty: '',
    distance: 10,
    acceptingPatients: true
  });

  // Use host auth token for API calls
  const searchProviders = async () => {
    const results = await providerApi.search(filters, {
      headers: { Authorization: `Bearer ${authToken}` }
    });
    // ...
  };

  return <FiltersUI filters={filters} onChange={setFilters} />;
};
```

> **Token Handling Security:** Bearer tokens read from Redux state are visible in Redux DevTools and serializable to the browser. Ensure Redux DevTools are disabled in all non-local environments (see [GUID-APP-TEC-002](../state-management/GUID-APP-TEC-002-zustand-over-redux-guidance.md) `devTools: process.env.NODE_ENV !== 'production'`) and the auth token slice is excluded from DevTools serialization via `stateSanitizer`. Prefer backend-for-frontend (BFF) patterns where the server attaches tokens transparently rather than forwarding raw tokens through the client. Refer to [STD-SEC-AUTHN-001 §3.7 API Authentication](../../../../standards/security/authentication/STD-SEC-AUTHN-001-authentication-implementation.md).

