[strategy/guidance/application/implementation/GUID-APP-IMPL-002-extension-pattern-cookbook.md#integration-points]

#### Integration Points

**Backend Workflow State Machine:**

```csharp
// Extensions/Workflows/EligibilityDeterminationWorkflow.cs
public class EligibilityDeterminationWorkflow : WorkflowBase
{
    private readonly IWorkflowStateRepository _stateRepository;
    private readonly IEligibilityService _eligibilityService;

    public EligibilityDeterminationWorkflow(
        IWorkflowStateRepository stateRepository,
        IEligibilityService eligibilityService)
    {
        _stateRepository = stateRepository;
        _eligibilityService = eligibilityService;

        // Define workflow states and transitions
        DefineState("Start", isInitial: true);
        DefineState("CollectApplicantInfo");
        DefineState("VerifyIdentity");
        DefineState("DetermineEligibility");
        DefineState("ReviewResults");
        DefineState("Completed", isFinal: true);

        // Define transitions
        DefineTransition("Start", "CollectApplicantInfo", "Begin");
        DefineTransition("CollectApplicantInfo", "VerifyIdentity", "Submit");
        DefineTransition("VerifyIdentity", "DetermineEligibility", "Verified");
        DefineTransition("VerifyIdentity", "CollectApplicantInfo", "VerificationFailed", compensation: true);
        DefineTransition("DetermineEligibility", "ReviewResults", "Determined");
        DefineTransition("ReviewResults", "Completed", "Approve");
    }

    protected override async Task<WorkflowResult> ExecuteStateAsync(
        string stateName,
        WorkflowContext context,
        CancellationToken ct)
    {
        return stateName switch
        {
            "VerifyIdentity" => await VerifyIdentityAsync(context, ct),
            "DetermineEligibility" => await DetermineEligibilityAsync(context, ct),
            _ => WorkflowResult.Success()
        };
    }

    private async Task<WorkflowResult> VerifyIdentityAsync(WorkflowContext context, CancellationToken ct)
    {
        var applicant = context.GetData<ApplicantInfo>("applicant");
        var verificationResult = await _eligibilityService.VerifyIdentityAsync(applicant, ct);

        if (verificationResult.IsVerified)
        {
            context.SetData("verificationId", verificationResult.VerificationId);
            return WorkflowResult.Transition("Verified");
        }
        else
        {
            return WorkflowResult.Transition("VerificationFailed", error: verificationResult.Error);
        }
    }
}

// API Controller triggering workflow
[HttpPost("api/eligibility/workflows")]
public async Task<ActionResult<WorkflowResponse>> StartWorkflowAsync([FromBody] StartWorkflowRequest request)
{
    var workflow = _workflowFactory.Create<EligibilityDeterminationWorkflow>();
    var workflowId = await workflow.StartAsync(request.InitialData);

    return Ok(new WorkflowResponse { WorkflowId = workflowId, CurrentState = "CollectApplicantInfo" });
}

[HttpPost("api/eligibility/workflows/{workflowId}/transition")]
public async Task<ActionResult<WorkflowResponse>> TransitionAsync(
    string workflowId,
    [FromBody] TransitionRequest request)
{
    var workflow = await _workflowRepository.LoadAsync<EligibilityDeterminationWorkflow>(workflowId);
    var result = await workflow.TransitionAsync(request.Event, request.Data);

    if (result.Success)
    {
        return Ok(new WorkflowResponse
        {
            WorkflowId = workflowId,
            CurrentState = result.NewState,
            Data = result.Data
        });
    }
    else
    {
        return BadRequest(new { Error = result.Error });
    }
}
```

**Frontend Wizard:**

```typescript
// Extensions/Wizards/EligibilityDeterminationWizard.tsx
import { WizardShell, WizardStep, useWizard } from '@product/wizard-framework';

export const EligibilityDeterminationWizard: React.FC = () => {
  const { workflowId, currentStep, stepData, isSubmitting, error } = useWizard({
    workflowApi: '/api/eligibility/workflows',
    initialStep: 'applicant-info'
  });

  const handleStepComplete = async (stepId: string, data: any) => {
    // Call workflow API to transition (integrates PTN-APP-EXT-011)
    await transitionWorkflow(workflowId, 'Submit', { [stepId]: data });
  };

  return (
    <WizardShell
      currentStep={currentStep}
      onStepComplete={handleStepComplete}
      error={error}
    >
      {/* PTN-APP-EXT-014: Steps registered as extension points */}
      <WizardStep id="applicant-info" title="Applicant Information">
        <ApplicantInfoForm />
      </WizardStep>

      <WizardStep id="identity-verification" title="Identity Verification">
        <IdentityVerificationForm />
      </WizardStep>

      <WizardStep id="eligibility-questions" title="Eligibility Questions">
        <EligibilityQuestionsForm />
      </WizardStep>

      <WizardStep id="review" title="Review & Submit">
        <ReviewAndSubmitForm data={stepData} />
      </WizardStep>
    </WizardShell>
  );
};

// Wizard step component with validation
const ApplicantInfoForm: React.FC<StepProps> = ({ onComplete, initialData }) => {
  const [formData, setFormData] = useState(initialData || {});
  const [errors, setErrors] = useState({});

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Client-side validation
    const validationErrors = validateApplicantInfo(formData);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    // Server-side validation via API
    const serverValidation = await validateWithServer(formData);
    if (!serverValidation.valid) {
      setErrors(serverValidation.errors);
      return;
    }

    // Proceed to next step
    onComplete(formData);
  };

  return (
    <form onSubmit={handleSubmit}>
      {/* Form fields */}
      <button type="submit">Continue</button>
    </form>
  );
};
```

**Extension Point Registration (PTN-APP-EXT-014):**

```typescript
// Allow states to add/remove wizard steps without modifying wizard shell
export interface WizardStepExtension {
  id: string;
  title: string;
  component: React.ComponentType<StepProps>;
  position?: number;  // Insert position
  condition?: (context: WizardContext) => boolean;  // Conditional rendering
}

// Extension point registry
const wizardStepRegistry = new ExtensionPointRegistry<WizardStepExtension>();

// States can register additional steps
wizardStepRegistry.register({
  id: 'texas-specific-questions',
  title: 'Texas-Specific Eligibility Questions',
  component: TexasEligibilityQuestions,
  position: 3,  // Insert after eligibility-questions
  condition: (ctx) => ctx.stateCode === 'TX'
});

// Wizard shell dynamically loads steps from registry
const WizardShell: React.FC = () => {
  const registeredSteps = wizardStepRegistry.getAll();
  const applicableSteps = registeredSteps.filter(step =>
    !step.condition || step.condition(wizardContext)
  );
  const sortedSteps = sortBy(applicableSteps, 'position');

  return (
    <div>
      {sortedSteps.map(step => (
        <WizardStep key={step.id} {...step} />
      ))}
    </div>
  );
};
```

