**Tenant MFE Loader (PTN-APP-MTN-012):**

```typescript
// Shared/MFELoader/TenantMFELoader.tsx
import { useTenantContext } from '@product/tenant-context';
import { useTenantMFEConfiguration } from './hooks/useTenantMFEConfiguration';

export const TenantMFELoader: React.FC<TenantMFELoaderProps> = ({ route, fallback }) => {
  const { tenantId } = useTenantContext();
  const { mfeConfig, loading, error } = useTenantMFEConfiguration(tenantId);

  // Find MFE matching current route
  const applicableMFE = mfeConfig?.mfes.find(mfe =>
    mfe.enabled && mfe.routes?.some(r => route.startsWith(r))
  );

  if (loading) {
    return <MFELoadingSkeleton />;
  }

  if (error) {
    console.error(`Failed to load tenant MFE config for ${tenantId}:`, error);
    return fallback || <DefaultComponent />;
  }

  if (!applicableMFE) {
    // Tenant doesn't have custom MFE for this route, use default
    return fallback || <DefaultComponent />;
  }

  // Load tenant-specific MFE dynamically
  return (
    <Suspense fallback={<MFELoadingSkeleton />}>
      <DynamicMFE
        remoteEntry={applicableMFE.remoteEntry}
        scope={applicableMFE.scope}
        module={applicableMFE.module}
        fallback={fallback}
        tenantId={tenantId}
      />
    </Suspense>
  );
};

// Dynamic MFE loader with error boundary
const DynamicMFE: React.FC<DynamicMFEProps> = ({
  remoteEntry,
  scope,
  module,
  fallback,
  tenantId
}) => {
  const [MFEComponent, setMFEComponent] = useState<React.ComponentType | null>(null);
  const [loadError, setLoadError] = useState<Error | null>(null);

  useEffect(() => {
    let mounted = true;

    const loadMFE = async () => {
      try {
        // Health check MFE before loading
        const healthCheckUrl = remoteEntry.replace('remoteEntry.js', 'health');
        const healthResponse = await fetch(healthCheckUrl, { method: 'HEAD', timeout: 2000 });

        if (!healthResponse.ok) {
          throw new Error(`MFE health check failed: ${healthResponse.status}`);
        }

        // Load MFE script
        await loadRemoteModule(remoteEntry, scope);

        // Import module
        const container = (window as any)[scope];
        await container.init(__webpack_share_scopes__.default);
        const factory = await container.get(module);
        const Module = factory();

        if (mounted) {
          setMFEComponent(() => Module.default || Module);

          // Track successful MFE load
          trackMFELoad(tenantId, scope, 'success');
        }
      } catch (error) {
        console.error(`Failed to load MFE ${scope} for tenant ${tenantId}:`, error);
        setLoadError(error as Error);

        // Track failed MFE load
        trackMFELoad(tenantId, scope, 'failure', error);
      }
    };

    loadMFE();

    return () => {
      mounted = false;
    };
  }, [remoteEntry, scope, module, tenantId]);

  if (loadError) {
    // MFE failed to load, use fallback
    console.warn(`Using fallback for tenant ${tenantId} MFE ${scope}`);
    return fallback || <DefaultComponent />;
  }

  if (!MFEComponent) {
    return <MFELoadingSkeleton />;
  }

  // Wrap MFE in error boundary for isolation (PTN-APP-EXT-016)
  return (
    <MFEErrorBoundary tenantId={tenantId} mfeScope={scope} fallback={fallback}>
      <TenantIsolationProvider tenantId={tenantId}>
        <MFEComponent />
      </TenantIsolationProvider>
    </MFEErrorBoundary>
  );
};

// Error boundary isolating MFE failures (PTN-APP-EXT-016)
class MFEErrorBoundary extends React.Component<MFEErrorBoundaryProps, MFEErrorBoundaryState> {
  state = { hasError: false, error: null };

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    // Log MFE error, don't propagate to host
    console.error(`MFE ${this.props.mfeScope} error for tenant ${this.props.tenantId}:`, error, errorInfo);

    // Track MFE runtime error
    trackMFEError(this.props.tenantId, this.props.mfeScope, error);
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback || <MFEErrorFallback error={this.state.error} />;
    }

    return this.props.children;
  }
}

// Tenant isolation provider ensuring MFE can't access other tenants' data
const TenantIsolationProvider: React.FC<{ tenantId: string; children: React.ReactNode }> = ({
  tenantId,
  children
}) => {
  const isolatedContext = useMemo(() => ({
    tenantId,
    // Provide only tenant-scoped APIs to MFE
    apiClient: createTenantScopedApiClient(tenantId),
    storage: createTenantScopedStorage(tenantId),
    // ... other tenant-scoped services
  }), [tenantId]);

  return (
    <TenantContext.Provider value={isolatedContext}>
      {children}
    </TenantContext.Provider>
  );
};
```

