#### Integration Points

**Entity Framework Extension (PTN-APP-EXT-007):**

```csharp
// Product entity (from product codebase, don't modify)
public class Provider
{
    public int Id { get; set; }
    public string Name { get; set; }
    public string NPI { get; set; }
    public string Specialty { get; set; }
    // ... other product properties
}

// Custom entity extension (Texas-specific fields)
// Option 1: Partial class (if product allows)
public partial class Provider
{
    // Texas-specific custom properties
    public string TexasLicenseNumber { get; set; }
    public DateTime? TexasLicenseExpiration { get; set; }
    public string TexasMedicaidProviderId { get; set; }
    public bool TexasCredentialVerified { get; set; }
}

// Option 2: Shadow properties (if can't modify product entity class)
public class TexasProviderExtension
{
    public int ProviderId { get; set; }  // FK to Provider.Id
    public Provider Provider { get; set; }

    public string TexasLicenseNumber { get; set; }
    public DateTime? TexasLicenseExpiration { get; set; }
    public string TexasMedicaidProviderId { get; set; }
    public bool TexasCredentialVerified { get; set; }
}

// Entity Framework DbContext extension
public class CustomDbContext : ProductDbContext
{
    public DbSet<TexasProviderExtension> TexasProviderExtensions { get; set; }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        // Configure custom entity (Option 2: shadow properties)
        modelBuilder.Entity<TexasProviderExtension>(entity =>
        {
            entity.ToTable("Providers_TexasExtension");
            entity.HasKey(e => e.ProviderId);

            entity.HasOne(e => e.Provider)
                  .WithOne()
                  .HasForeignKey<TexasProviderExtension>(e => e.ProviderId)
                  .OnDelete(DeleteBehavior.Cascade);

            entity.Property(e => e.TexasLicenseNumber)
                  .HasMaxLength(50)
                  .IsRequired();

            entity.HasIndex(e => e.TexasLicenseNumber);
            entity.HasIndex(e => e.TexasMedicaidProviderId);
        });
    }
}
```

**Database Migration Script:**

