**Custom Repository (PTN-APP-EXT-001):**

```csharp
// Custom repository for Texas provider data
public interface ITexasProviderRepository
{
    Task<TexasProviderExtension> GetByProviderIdAsync(int providerId, CancellationToken ct);
    Task<IEnumerable<TexasProviderExtension>> GetByLicenseNumberAsync(string licenseNumber, CancellationToken ct);
    Task<IEnumerable<TexasProviderExtension>> GetExpiring SoonAsync(int daysThreshold, CancellationToken ct);
    Task AddOrUpdateAsync(TexasProviderExtension extension, CancellationToken ct);
    Task DeleteAsync(int providerId, CancellationToken ct);
}

public class TexasProviderRepository : ITexasProviderRepository
{
    private readonly CustomDbContext _context;

    public TexasProviderRepository(CustomDbContext context)
    {
        _context = context;
    }

    public async Task<TexasProviderExtension> GetByProviderIdAsync(int providerId, CancellationToken ct)
    {
        return await _context.TexasProviderExtensions
            .Include(e => e.Provider)
            .FirstOrDefaultAsync(e => e.ProviderId == providerId, ct);
    }

    public async Task<IEnumerable<TexasProviderExtension>> GetByLicenseNumberAsync(
        string licenseNumber,
        CancellationToken ct)
    {
        return await _context.TexasProviderExtensions
            .Include(e => e.Provider)
            .Where(e => e.TexasLicenseNumber == licenseNumber)
            .ToListAsync(ct);
    }

    public async Task<IEnumerable<TexasProviderExtension>> GetExpiringSoonAsync(
        int daysThreshold,
        CancellationToken ct)
    {
        var thresholdDate = DateTime.UtcNow.AddDays(daysThreshold);

        return await _context.TexasProviderExtensions
            .Include(e => e.Provider)
            .Where(e => e.TexasLicenseExpiration.HasValue &&
                        e.TexasLicenseExpiration.Value <= thresholdDate)
            .ToListAsync(ct);
    }

    public async Task AddOrUpdateAsync(TexasProviderExtension extension, CancellationToken ct)
    {
        var existing = await _context.TexasProviderExtensions
            .FindAsync(new object[] { extension.ProviderId }, ct);

        if (existing == null)
        {
            _context.TexasProviderExtensions.Add(extension);
        }
        else
        {
            _context.Entry(existing).CurrentValues.SetValues(extension);
        }

        await _context.SaveChangesAsync(ct);
    }

    public async Task DeleteAsync(int providerId, CancellationToken ct)
    {
        var extension = await _context.TexasProviderExtensions.FindAsync(new object[] { providerId }, ct);
        if (extension != null)
        {
            _context.TexasProviderExtensions.Remove(extension);
            await _context.SaveChangesAsync(ct);
        }
    }
}

// Register in DI
services.AddScoped<ITexasProviderRepository, TexasProviderRepository>();
```

**API Controller Using Custom Data:**

> **Authorization Requirement:** All extension API controllers handling PHI-adjacent data must include `[Authorize]` at the class level at minimum. Apply tenant-scoped authorization policies to restrict access to the correct state tenant. Refer to [STD-SEC-AUTHZ-001 §3.1 RBAC](../../../../standards/security/authorization/STD-SEC-AUTHZ-001-authorization-implementation.md) and [STD-SEC-APP-001 §3.1](../../../../standards/security/application/STD-SEC-APP-001-application-security.md).

```csharp
[ApiController]
[Route("api/texas/providers")]
[Authorize]  // Required: all endpoints in this controller require a valid authenticated JWT
public class TexasProvidersController : ControllerBase
{
    private readonly ITexasProviderRepository _texasProviderRepo;
    private readonly IProviderRepository _productProviderRepo;  // Product repository

    public TexasProvidersController(
        ITexasProviderRepository texasProviderRepo,
        IProviderRepository productProviderRepo)
    {
        _texasProviderRepo = texasProviderRepo;
        _productProviderRepo = productProviderRepo;
    }

    [HttpGet("{providerId}")]
    [Authorize(Policy = "TexasTenantAccess")]  // Scope to Texas-authorized users only
    public async Task<ActionResult<TexasProviderDto>> GetAsync(int providerId, CancellationToken ct)
    {
        // Get product provider data
        var provider = await _productProviderRepo.GetByIdAsync(providerId, ct);
        if (provider == null)
        {
            return NotFound();
        }

        // Get Texas-specific extension data
        var texasExtension = await _texasProviderRepo.GetByProviderIdAsync(providerId, ct);

        // Combine product and custom data in DTO
        return Ok(new TexasProviderDto
        {
            // Product fields
            Id = provider.Id,
            Name = provider.Name,
            NPI = provider.NPI,
            Specialty = provider.Specialty,

            // Texas-specific fields
            TexasLicenseNumber = texasExtension?.TexasLicenseNumber,
            TexasLicenseExpiration = texasExtension?.TexasLicenseExpiration,
            TexasMedicaidProviderId = texasExtension?.TexasMedicaidProviderId,
            TexasCredentialVerified = texasExtension?.TexasCredentialVerified ?? false
        });
    }

    [HttpGet("expiring")]
    public async Task<ActionResult<IEnumerable<TexasProviderDto>>> GetExpiringSoonAsync(
        [FromQuery] int days = 30,
        CancellationToken ct = default)
    {
        var expiring = await _texasProviderRepo.GetExpiringSoonAsync(days, ct);

        // Map to DTOs
        var dtos = expiring.Select(e => new TexasProviderDto
        {
            Id = e.Provider.Id,
            Name = e.Provider.Name,
            NPI = e.Provider.NPI,
            Specialty = e.Provider.Specialty,
            TexasLicenseNumber = e.TexasLicenseNumber,
            TexasLicenseExpiration = e.TexasLicenseExpiration,
            TexasMedicaidProviderId = e.TexasMedicaidProviderId,
            TexasCredentialVerified = e.TexasCredentialVerified
        });

        return Ok(dtos);
    }
}
```

