// Extensions/ClaimsSummaryWidget/ClaimsSummaryWidget.tsx
import { useSelector, useDispatch } from 'react-redux';
import { useProductState } from '@product/state-management';

export const ClaimsSummaryWidget: React.FC = () => {
  const dispatch = useDispatch();

  // Read from product state (PTN-APP-EXT-018)
  const { user, claims, selectedClaim } = useSelector((state: ProductRootState) => ({
    user: state.auth.user,
    claims: state.claims.list,
    selectedClaim: state.claims.selectedClaim
  }));

  // Local component state (doesn't need to be in Redux)
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({});

  // Calculate summary metrics from product state
  const summary = useMemo(() => ({
    totalClaims: claims.length,
    pendingClaims: claims.filter(c => c.status === 'Pending').length,
    approvedClaims: claims.filter(c => c.status === 'Approved').length,
    deniedClaims: claims.filter(c => c.status === 'Denied').length,
    totalAmount: claims.reduce((sum, c) => sum + c.amount, 0)
  }), [claims]);

  // Dispatch action to product state (PTN-APP-EXT-018)
  const handleClaimClick = (claimId: string) => {
    dispatch(productActions.selectClaim(claimId));

    // Track analytics (custom action not in product state)
    trackEvent('claim_selected_from_widget', { claimId });
  };

  return (
    <Card title="Claims Summary">
      <SummaryMetrics>
        <Metric label="Total Claims" value={summary.totalClaims} />
        <Metric label="Pending" value={summary.pendingClaims} variant="warning" />
        <Metric label="Approved" value={summary.approvedClaims} variant="success" />
        <Metric label="Denied" value={summary.deniedClaims} variant="error" />
        <Metric label="Total Amount" value={formatCurrency(summary.totalAmount)} />
      </SummaryMetrics>

      {selectedClaim && (
        <SelectedClaimDetails
          claim={selectedClaim}
          user={user}
          onStatusChange={(newStatus) => {
            // Optimistic update with rollback on error
            const previousStatus = selectedClaim.status;
            dispatch(productActions.updateClaimStatus(selectedClaim.id, newStatus));

            updateClaimStatusApi(selectedClaim.id, newStatus)
              .catch(error => {
                // Rollback on API error
                dispatch(productActions.updateClaimStatus(selectedClaim.id, previousStatus));
                showErrorToast('Failed to update claim status');
              });
          }}
        />
      )}

      <RecentClaimsList
        claims={claims.slice(0, 5)}
        onClaimClick={handleClaimClick}
      />
    </Card>
  );
};

// Performance optimization: memoized selectors
const selectClaimsSummary = createSelector(
  (state: ProductRootState) => state.claims.list,
  (claims) => ({
    totalClaims: claims.length,
    pendingClaims: claims.filter(c => c.status === 'Pending').length,
    approvedClaims: claims.filter(c => c.status === 'Approved').length,
    deniedClaims: claims.filter(c => c.status === 'Denied').length,
    totalAmount: claims.reduce((sum, c) => sum + c.amount, 0)
  })
);

// Optimized component with memoized selector
export const ClaimsSummaryWidgetOptimized: React.FC = () => {
  const summary = useSelector(selectClaimsSummary);
  // Only re-renders when summary values change, not when unrelated state changes
  return <SummaryMetrics summary={summary} />;
};
```

