// tests/compatibility/frontend-compatibility.test.ts
import { render, waitFor } from '@testing-library/react';
import { setupServer } from 'msw/node';
import { rest } from 'msw';

const PRODUCT_VERSIONS = ['2.4.0', '2.5.0', '2.6.0'];

describe('Frontend Compatibility Tests', () => {
  PRODUCT_VERSIONS.forEach(version => {
    describe(`Product Version ${version}`, () => {
      let server;

      beforeAll(() => {
        // Mock API with version-specific responses
        server = setupServer(
          rest.get('/api/claims', (req, res, ctx) => {
            // Return version-specific response format
            return res(ctx.json(getClaimsResponseForVersion(version)));
          })
        );
        server.listen();
      });

      afterAll(() => server.close());

      it(`should render TexasClaimsWidget with product v${version}`, async () => {
        // Set product version in test environment
        process.env.PRODUCT_VERSION = version;

        const { getByText, getByTestId } = render(<TexasClaimsWidget />);

        // Widget should render regardless of product version
        expect(getByTestId('texas-claims-widget')).toBeInTheDocument();

        // Wait for data to load
        await waitFor(() => {
          expect(getByText(/Total Claims:/)).toBeInTheDocument();
        });
      });

      it(`should handle API response format for v${version}`, async () => {
        const apiClient = createApiClient(version);
        const response = await apiClient.getClaims();

        // Response should be normalized regardless of version
        expect(response).toHaveProperty('claims');
        expect(Array.isArray(response.claims)).toBe(true);
      });

      it(`should use design system components from v${version}`, () => {
        const designSystem = loadDesignSystem(version);
        const { getByRole } = render(
          <designSystem.ThemeProvider>
            <TexasClaimsWidget />
          </designSystem.ThemeProvider>
        );

        // Design system components should render
        expect(getByRole('button')).toBeInTheDocument();
      });
    });
  });
});

// Helper: Version-specific API response formats
function getClaimsResponseForVersion(version: string) {
  switch (version) {
    case '2.4.0':
      // Legacy format
      return {
        data: {
          claimsList: [
            { claimId: '1', claimStatus: 'pending', claimAmount: 1000 }
          ]
        }
      };

    case '2.5.0':
    case '2.6.0':
      // New format
      return {
        claims: [
          { id: '1', status: 'Pending', amount: 1000 }
        ],
        total: 1,
        page: 1
      };

    default:
      throw new Error(`Unsupported version: ${version}`);
  }
}

// API client with version adaptation
class VersionAdaptiveApiClient {
  constructor(private version: string) {}

  async getClaims(): Promise<ClaimsResponse> {
    const response = await fetch('/api/claims');
    const data = await response.json();

    // Normalize response based on product version
    if (this.version === '2.4.0') {
      // Adapter for legacy format
      return {
        claims: data.data.claimsList.map(c => ({
          id: c.claimId,
          status: capitalize(c.claimStatus),
          amount: c.claimAmount
        })),
        total: data.data.claimsList.length,
        page: 1
      };
    } else {
      // New format doesn't need adaptation
      return data;
    }
  }
}
```

