**CI/CD Integration:**

```yaml
# .github/workflows/compatibility-tests.yml
name: Compatibility Tests

on: [push, pull_request]

jobs:
  frontend-compatibility:
    name: Frontend Compatibility - Product v${{ matrix.product-version }}
    runs-on: ubuntu-latest
    strategy:
      matrix:
        product-version: ['2.4.0', '2.5.0', '2.6.0']
    steps:
      - uses: actions/checkout@v3

      - name: Setup Node
        uses: actions/setup-node@v3
        with:
          node-version: '18'

      - name: Install dependencies
        run: npm ci

      - name: Install product version ${{ matrix.product-version }}
        run: |
          npm install @product/api-client@${{ matrix.product-version }}
          npm install @product/design-system@${{ matrix.product-version }}

      - name: Run compatibility tests
        run: npm run test:compatibility -- --product-version=${{ matrix.product-version }}

      - name: Upload test results
        uses: actions/upload-artifact@v3
        with:
          name: frontend-compatibility-${{ matrix.product-version }}
          path: test-results/

  backend-compatibility:
    name: Backend Compatibility - Product v${{ matrix.product-version }}
    runs-on: ubuntu-latest
    strategy:
      matrix:
        product-version: ['2.4.0', '2.5.0', '2.6.0']
    steps:
      - uses: actions/checkout@v3

      - name: Setup .NET
        uses: actions/setup-dotnet@v3
        with:
          dotnet-version: '8.0.x'

      - name: Install product assemblies v${{ matrix.product-version }}
        run: |
          mkdir -p ./ProductAssemblies/v${{ matrix.product-version }}
          dotnet restore --source https://nuget.product.com/v3/index.json
          # Download product NuGet packages for version

      - name: Run compatibility tests
        run: dotnet test --filter "Category=Compatibility" -- ProductVersion=${{ matrix.product-version }}

      - name: Upload test results
        uses: actions/upload-artifact@v3
        with:
          name: backend-compatibility-${{ matrix.product-version }}
          path: TestResults/

  compatibility-report:
    name: Generate Compatibility Report
    needs: [frontend-compatibility, backend-compatibility]
    runs-on: ubuntu-latest
    steps:
      - name: Download all test results
        uses: actions/download-artifact@v3

      - name: Generate compatibility matrix report
        run: |
          node scripts/generate-compatibility-report.js

      - name: Upload compatibility report
        uses: actions/upload-artifact@v3
        with:
          name: compatibility-report
          path: compatibility-report.html
```

