// Tests/Isolated/TexasRuleEngineIsolatedTests.cs
[TestFixture]
public class TexasRuleEngineIsolatedTests
{
    private TexasClaimsRuleEngine _ruleEngine;
    private Mock<IProviderRegistryClient> _mockProviderRegistry;
    private Mock<IPolicyService> _mockPolicyService;

    [SetUp]
    public void SetUp()
    {
        // Mock all product dependencies
        _mockProviderRegistry = new Mock<IProviderRegistryClient>();
        _mockPolicyService = new Mock<IPolicyService>();

        // Create rule engine with mocked dependencies (no product required)
        _ruleEngine = new TexasClaimsRuleEngine(
            _mockProviderRegistry.Object,
            _mockPolicyService.Object
        );
    }

    [Test]
    public async Task ValidateClaim_ProviderHasValidCredential_ShouldPass()
    {
        // Arrange: Mock provider registry response (no actual API call)
        _mockProviderRegistry
            .Setup(r => r.GetProviderAsync("TX-PROVIDER-123", "TX", It.IsAny<CancellationToken>()))
            .ReturnsAsync(new Provider
            {
                Id = "TX-PROVIDER-123",
                Name = "Test Provider",
                Credentials = new[]
                {
                    new Credential
                    {
                        Type = "Surgery",
                        IsActive = true,
                        ExpirationDate = DateTime.UtcNow.AddYears(1)
                    }
                }
            });

        var claim = new Claim
        {
            ProviderId = "TX-PROVIDER-123",
            ServiceType = "Surgery",
            Amount = 5000
        };

        // Act: Execute rule engine in isolation
        var result = await _ruleEngine.ValidateAsync(claim, CancellationToken.None);

        // Assert: Should pass validation
        Assert.IsTrue(result.IsValid);
    }

    [Test]
    public async Task ValidateClaim_ProviderMissingCredential_ShouldFail()
    {
        // Arrange: Provider without required credential
        _mockProviderRegistry
            .Setup(r => r.GetProviderAsync("TX-PROVIDER-456", "TX", It.IsAny<CancellationToken>()))
            .ReturnsAsync(new Provider
            {
                Id = "TX-PROVIDER-456",
                Name = "Test Provider",
                Credentials = new Credential[0]  // No credentials
            });

        var claim = new Claim
        {
            ProviderId = "TX-PROVIDER-456",
            ServiceType = "Surgery",
            Amount = 5000
        };

        // Act
        var result = await _ruleEngine.ValidateAsync(claim, CancellationToken.None);

        // Assert: Should fail validation
        Assert.IsFalse(result.IsValid);
        Assert.That(result.Errors, Contains.Item("Provider lacks active credentials for Surgery in Texas"));
    }
}

// Test harness for manual testing
public class RuleEngineTestHarness
{
    public static async Task Main(string[] args)
    {
        // Create in-memory stub implementations (no product needed)
        var providerRegistry = new InMemoryProviderRegistry();
        var policyService = new InMemoryPolicyService();

        var ruleEngine = new TexasClaimsRuleEngine(providerRegistry, policyService);

        // Load test claims from JSON
        var testClaims = LoadTestClaims("./test-data/claims.json");

        // Execute rule engine against test claims
        foreach (var claim in testClaims)
        {
            var result = await ruleEngine.ValidateAsync(claim, CancellationToken.None);
            Console.WriteLine($"Claim {claim.Id}: {(result.IsValid ? "VALID" : "INVALID")}");

            if (!result.IsValid)
            {
                foreach (var error in result.Errors)
                {
                    Console.WriteLine($"  - {error}");
                }
            }
        }
    }
}
