```yaml
# .github/workflows/extension-ci.yml
name: Extension CI/CD

on:
  push:
    branches: [main, develop]
  pull_request:

jobs:
  test:
    name: Test Extension (Isolated)
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3

      - name: Setup Node
        uses: actions/setup-node@v3

      - name: Install dependencies
        run: npm ci

      - name: Run isolated unit tests (no product needed)
        run: npm run test:isolated

      - name: Run Storybook tests
        run: npm run test:storybook

      - name: Build extension package
        run: npm run build

      - name: Package extension
        run: npm pack

  integration:
    name: Integration Test with Product
    needs: test
    runs-on: ubuntu-latest
    steps:
      - name: Download product test environment
        run: |
          # Download product Docker container or mocked version
          docker pull product/claims-system:latest

      - name: Install extension in product
        run: |
          # Install extension package in product environment
          docker run -v $(pwd):/extension product/claims-system:latest \
            extension install /extension/*.tgz

      - name: Run integration tests
        run: |
          docker run product/claims-system:latest \
            extension test texas-claims-validation

  publish:
    name: Publish Extension
    needs: [test, integration]
    if: github.ref == 'refs/heads/main'
    runs-on: ubuntu-latest
    steps:
      - name: Publish to extension registry
        run: |
          npm publish --registry https://extensions.company.com/

      - name: Create GitHub release
        uses: actions/create-release@v1
        with:
          tag_name: v${{ github.run_number }}
          release_name: Release v${{ github.run_number }}
